#include <stdio.h>

int main(void) {
    int A, L;
    if (scanf("%d %d", &A, &L) != 2) return 0;

    int N;
    if (scanf("%d", &N) != 1) return 0;

    int best_id = -1;
    long long min_area = -1;

    for (int i = 1; i <= N; ++i) {
        int X, Y;
        scanf("%d %d", &X, &Y);

        if ((A <= X && L <= Y) || (A <= Y && L <= X)) {
            long long area = (long long)X * Y;
            if (best_id == -1 || area < min_area) {
                min_area = area;
                best_id = i;
            }
        }
    }

    printf("%d\n", best_id);

    return 0;
}
